# Rebuilds the illustrated user guide (docs/guide) as one self-contained HTML file.
#   1. demo data   - fictional tickets generated by the real backend   (src-tauri/src/demo.rs)
#   2. screenshots - the real UI in Microsoft Edge on that demo data      (docs/guide/capture.py)
#   3. render      - Quarto -> docs/guide/ASR-Support-Desk-User-Guide.html, also copied to %USERPROFILE%\Documents
# Requirements: Python with playwright, Microsoft Edge, Node (node_modules), portable Quarto in
# %LOCALAPPDATA%\Programs\quarto (see docs/BUILD_WINDOWS.md). Run in a normal (non-elevated) PowerShell.
param([switch]$SkipScreenshots)
. "$PSScriptRoot\env.ps1"
$quarto = Join-Path $env:LOCALAPPDATA "Programs\quarto\bin\quarto.exe"
if (-not (Test-Path $quarto)) { throw "Quarto not found at $quarto. See docs/BUILD_WINDOWS.md, 'Rebuilding the user guide'." }
if (-not (Test-Path node_modules)) { npm ci }

Write-Host "== 1/3 Demo data ==" -ForegroundColor Cyan
Push-Location src-tauri
cargo test --no-default-features -- --ignored write_docs_fixtures --quiet
if ($LASTEXITCODE -ne 0) { Pop-Location; throw "Generating demo data failed." }
Pop-Location

if (-not $SkipScreenshots) {
  Write-Host "== 2/3 Screenshots ==" -ForegroundColor Cyan
  python docs\guide\capture.py
  if ($LASTEXITCODE -ne 0) { throw "Screenshot capture failed." }
}

Write-Host "== 3/3 Render ==" -ForegroundColor Cyan
& $quarto render docs\guide\user-guide.qmd
if ($LASTEXITCODE -ne 0) { throw "Quarto render failed." }
$html = "docs\guide\_output\user-guide.html"
$final = "docs\guide\ASR-Support-Desk-User-Guide.html"
Copy-Item $html $final -Force
$docs = Join-Path $env:USERPROFILE "Documents\ASR-Support-Desk-User-Guide.html"
Copy-Item $html $docs -Force
$f = Get-Item $final
Write-Host ("Guide: {0} ({1:N1} MB)" -f $f.FullName, ($f.Length / 1MB)) -ForegroundColor Green
Write-Host "Copy:  $docs" -ForegroundColor Green
